import { LocalFileGroup } from './useFileTree'
import { SelectionItem } from './useSelection'

// All ancestor group keys of a group key, from outermost to the key itself
// — e.g. "invoices/2026/jan" -> ["invoices", "invoices/2026", "invoices/2026/jan"]
// — derived from the '/'-joined key scheme GroupNode/FileList use to
// identify groups, without needing to walk the tree.
function keyChain(groupKey: string): string[] {
  const parts = groupKey.split('/')
  return parts.map((_, i) => parts.slice(0, i + 1).join('/'))
}

// Maps every file's path to its immediate parent group's key, or null for a
// root-level file with no group to inherit from.
function fileParentKeys(tree: LocalFileGroup): Map<string, string | null> {
  const result = new Map<string, string | null>()
  const walk = (group: LocalFileGroup, groupKey: string | null) => {
    for (const file of group.files) result.set(file.path, groupKey)
    for (const sub of group.subgroups) {
      walk(sub, groupKey !== null ? `${groupKey}/${sub.name}` : sub.name)
    }
  }
  walk(tree, null)
  console.log(result)
  return result
}

// Drops any selected item that's a descendant of another selected subfolder,
// so a batch assignment gives only the topmost selected item in each
// subtree its own assignment and leaves the rest to inherit it — instead of
// pinning every descendant with a redundant override that could later
// diverge from its ancestor's.
export function pruneSelectionForAssignment(tree: LocalFileGroup, items: SelectionItem[]): SelectionItem[] {
  const selectedGroupKeys = new Set(items.filter(i => i.type === 'group').map(i => i.key))
  const parentKeys = fileParentKeys(tree)

  return items.filter(item => {
    if (item.type === 'group') {
      const ancestors = keyChain(item.key).slice(0, -1)
      return !ancestors.some(k => selectedGroupKeys.has(k))
    }
    const parentKey = parentKeys.get(item.path) ?? null
    if (parentKey === null) return true
    return !keyChain(parentKey).some(k => selectedGroupKeys.has(k))
  })
}

import { describe, it, expect } from 'vitest'
import { pruneSelectionForAssignment } from './pruneSelection'
import { LocalFileGroup } from './useFileTree'

function file(path: string) {
  return { path, name: path, sizeBytes: 0, isPdf: true, pageCount: 1, corrupt: false }
}

const TREE: LocalFileGroup = {
  name: '',
  files: [file('/root/misc.pdf')],
  subgroups: [
    {
      name: 'invoices',
      files: [file('/root/invoices/a.pdf'), file('/root/invoices/b.pdf')],
      subgroups: [
        { name: 'nested', files: [file('/root/invoices/nested/c.pdf')], subgroups: [] },
      ],
    },
    { name: 'receipts', files: [file('/root/receipts/d.pdf')], subgroups: [] },
  ],
}

describe('pruneSelectionForAssignment', () => {
  it('keeps a selection with no ancestor/descendant relationships untouched', () => {
    const items = [
      { type: 'file' as const, path: '/root/misc.pdf' },
      { type: 'group' as const, key: 'receipts' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })

  it('drops a file that is a descendant of a selected group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/invoices/a.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('drops a subgroup that is a descendant of a selected ancestor group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'group' as const, key: 'invoices/nested' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('drops a file nested two levels below a selected ancestor group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/invoices/nested/c.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('keeps a file selected alongside its sibling group, since it is not that group\'s descendant', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/receipts/d.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })

  it('a root-level file has no ancestor group and is never pruned', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/misc.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })
})

